@code {
    int currentStep = 1;
    int highestCompletedStep = 0;

    PersonalInfoModel personalInfo = new();
    List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    List<ReferenceModel> references = new() { new ReferenceModel() };
    string coverLetter = "";

    string? emailError;
    string? validationError;
    bool isSubmitting;
    bool isSubmitted;
    int? applicationId;

    void GoToStep(int step)
    {
        if (step <= highestCompletedStep + 1)
        {
            currentStep = step;
            validationError = null;
            emailError = null;
        }
    }

    async Task NextStep()
    {
        validationError = null;
        emailError = null;

        switch (currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(personalInfo.FullName) ||
                    string.IsNullOrWhiteSpace(personalInfo.Email) ||
                    string.IsNullOrWhiteSpace(personalInfo.Phone) ||
                    string.IsNullOrWhiteSpace(personalInfo.Address))
                {
                    validationError = "Please fill in all required fields.";
                    return;
                }
                var emailValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
                if (!emailValid)
                {
                    emailError = "Please enter a valid email address.";
                    return;
                }
                break;

            case 2:
                if (!workEntries.Any(e => !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title)))
                {
                    validationError = "At least one position must have a Company and Title.";
                    return;
                }
                break;

            case 3:
                if (!references.Any(r => !string.IsNullOrWhiteSpace(r.Name) && !string.IsNullOrWhiteSpace(r.Email)))
                {
                    validationError = "At least one reference must have a Name and Email.";
                    return;
                }
                break;

            case 4:
                break;
        }

        highestCompletedStep = Math.Max(highestCompletedStep, currentStep);
        currentStep++;
    }

    void PreviousStep()
    {
        if (currentStep > 1) currentStep--;
        validationError = null;
        emailError = null;
    }

    async Task SubmitApplication()
    {
        isSubmitting = true;
        StateHasChanged();

        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries
                .Where(e => !string.IsNullOrWhiteSpace(e.Company))
                .Select(e => new WorkEntry(e.Company, e.Title ?? "", e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description ?? ""))
                .ToList()),
            references
                .Where(r => !string.IsNullOrWhiteSpace(r.Name))
                .Select(r => new Reference(r.Name, r.Relationship ?? "", r.Email ?? "", r.Phone ?? ""))
                .ToList(),
            coverLetter ?? ""
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
        isSubmitted = true;
        StateHasChanged();
    }

    class PersonalInfoModel
    {
        public string FullName { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
        public string Address { get; set; } = "";
    }

    class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@page "/apply"
@rendermode InteractiveServer
