 @page "/apply"
 @rendermode InteractiveServer
 @inject IApplicationService ApplicationService

 <PageTitle>Job Application</PageTitle>

 <div class="container py-4" style="max-width: 800px;">
     <h2 class="mb-4 text-center">Job Application</h2>

     @if (isSubmitted)
     {
         <div class="text-center py-5">
             <div class="mb-4">
                 <span class="display-1 text-success">✓</span>
             </div>
             <h3 class="text-success">Application Submitted Successfully!</h3>
             <p class="lead mt-3">Your application ID is: <strong>#@applicationId</strong></p>
             <p class="text-muted">You will receive a confirmation email at <strong>@personalInfo.Email</strong>.</p>
         </div>
     }
     else
     {
         <!-- Step Indicator -->
         <div class="step-indicator mb-4">
             <div class="d-flex justify-content-between position-relative">
                 <div class="step-line"></div>
                 @for (int i = 1; i <= 5; i++)
                 {
                     var step = i;
                     var label = step switch { 1 => "Personal Info", 2 => "Work History", 3 => "References", 4 => "Cover Letter", _ => "Review & Submit" };
                     var isCompleted = step <= highestCompletedStep;
                     var isCurrent = step == currentStep;
                     <div class="step-item text-center" style="z-index: 1;">
                         @if (isCompleted)
                         {
                             <div class="step-circle bg-success text-white" role="button" @onclick="() => GoToStep(step)">✓</div>
                             <small class="step-label text-success fw-bold" role="button" @onclick="() => GoToStep(step)">@label</small>
                         }
                         else if (isCurrent)
                         {
                             <div class="step-circle bg-primary text-white">@step</div>
                             <small class="step-label text-primary fw-bold">@label</small>
                         }
                         else
                         {
                             <div class="step-circle bg-light text-muted border">@step</div>
                             <small class="step-label text-muted">@label</small>
                         }
                     </div>
                 }
             </div>
         </div>

         @if (!string.IsNullOrEmpty(validationError))
         {
             <div class="alert alert-danger">@validationError</div>
         }

         <!-- Step 1: Personal Info -->
         @if (currentStep == 1)
         {
             <div class="card">
                 <div class="card-body">
                     <h4 class="card-title mb-3">Personal Information</h4>
                     <div class="mb-3">
                         <label class="form-label">Full Name <span class="text-danger">*</span></label>
                         <input type="text" class="form-control" @bind="personalInfo.FullName" />
                     </div>
                     <div class="mb-3">
                         <label class="form-label">Email <span class="text-danger">*</span></label>
                         <input type="email" class="form-control" @bind="personalInfo.Email" />
                         @if (!string.IsNullOrEmpty(emailError))
                         {
                             <div class="text-danger mt-1"><small>@emailError</small></div>
                         }
                     </div>
                     <div class="mb-3">
                         <label class="form-label">Phone <span class="text-danger">*</span></label>
                         <input type="tel" class="form-control" @bind="personalInfo.Phone" />
                     </div>
                     <div class="mb-3">
                         <label class="form-label">Address <span class="text-danger">*</span></label>
                         <input type="text" class="form-control" @bind="personalInfo.Address" />
                     </div>
                     <div class="d-flex justify-content-end">
                         <button class="btn btn-primary" @onclick="NextStep">Next</button>
                     </div>
                 </div>
             </div>
         }
         <!-- Step 2: Work History -->
         else if (currentStep == 2)
         {
             <div class="card">
                 <div class="card-body">
                     <h4 class="card-title mb-3">Work History</h4>
                     @for (int i = 0; i < workEntries.Count; i++)
                     {
                         var index = i;
                         var entry = workEntries[index];
                         <div class="card mb-3">
                             <div class="card-body">
                                 <div class="d-flex justify-content-between align-items-center mb-2">
                                     <h6 class="mb-0">Position @(index + 1)</h6>
                                     @if (workEntries.Count > 1)
                                     {
                                         <button class="btn btn-outline-danger btn-sm" @onclick="() => workEntries.RemoveAt(index)">Remove</button>
                                     }
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Company <span class="text-danger">*</span></label>
                                     <input type="text" class="form-control" @bind="entry.Company" />
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Title <span class="text-danger">*</span></label>
                                     <input type="text" class="form-control" @bind="entry.Title" />
                                 </div>
                                 <div class="row mb-3">
                                     <div class="col-md-6">
                                         <label class="form-label">Start Date</label>
                                         <input type="date" class="form-control" @bind="entry.StartDate" />
                                     </div>
                                     <div class="col-md-6">
                                         <label class="form-label">End Date</label>
                                         <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                                     </div>
                                 </div>
                                 <div class="mb-3 form-check">
                                     <input type="checkbox" class="form-check-input" id="@($"current-{index}")" @bind="entry.IsCurrent" />
                                     <label class="form-check-label" for="@($"current-{index}")">I currently work here</label>
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Description</label>
                                     <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
                                 </div>
                             </div>
                         </div>
                     }
                     <button class="btn btn-outline-secondary mb-3" @onclick="() => workEntries.Add(new WorkEntryModel())">
                         + Add Another Position
                     </button>
                     <div class="d-flex justify-content-between">
                         <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                         <button class="btn btn-primary" @onclick="NextStep">Next</button>
                     </div>
                 </div>
             </div>
         }
         <!-- Step 3: References -->
         else if (currentStep == 3)
         {
             <div class="card">
                 <div class="card-body">
                     <h4 class="card-title mb-3">References</h4>
                     @for (int i = 0; i < references.Count; i++)
                     {
                         var index = i;
                         var reference = references[index];
                         <div class="card mb-3">
                             <div class="card-body">
                                 <div class="d-flex justify-content-between align-items-center mb-2">
                                     <h6 class="mb-0">Reference @(index + 1)</h6>
                                     @if (references.Count > 1)
                                     {
                                         <button class="btn btn-outline-danger btn-sm" @onclick="() => references.RemoveAt(index)">Remove</button>
                                     }
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Name <span class="text-danger">*</span></label>
                                     <input type="text" class="form-control" @bind="reference.Name" />
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Relationship</label>
                                     <input type="text" class="form-control" @bind="reference.Relationship" />
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Email <span class="text-danger">*</span></label>
                                     <input type="email" class="form-control" @bind="reference.Email" />
                                 </div>
                                 <div class="mb-3">
                                     <label class="form-label">Phone</label>
                                     <input type="tel" class="form-control" @bind="reference.Phone" />
                                 </div>
                             </div>
                         </div>
                     }
                     @if (references.Count < 3)
                     {
                         <button class="btn btn-outline-secondary mb-3" @onclick="() => references.Add(new ReferenceModel())">
                             + Add Reference
                         </button>
                     }
                     <div class="d-flex justify-content-between">
                         <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                         <button class="btn btn-primary" @onclick="NextStep">Next</button>
                     </div>
                 </div>
             </div>
         }
         <!-- Step 4: Cover Letter -->
         else if (currentStep == 4)
         {
             <div class="card">
                 <div class="card-body">
                     <h4 class="card-title mb-3">Cover Letter</h4>
                     <div class="mb-3">
                         <textarea class="form-control" rows="10" maxlength="2000" @bind="coverLetter" placeholder="Write your cover letter here (optional)..."></textarea>
                         <small class="text-muted">@(coverLetter?.Length ?? 0) / 2000 characters</small>
                     </div>
                     <div class="d-flex justify-content-between">
                         <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                         <button class="btn btn-primary" @onclick="NextStep">Next</button>
                     </div>
                 </div>
             </div>
         }
         <!-- Step 5: Review & Submit -->
         else if (currentStep == 5)
         {
             <div>
                 <!-- Personal Info Review -->
                 <div class="card mb-3">
                     <div class="card-body">
                         <div class="d-flex justify-content-between align-items-center mb-2">
                             <h5 class="card-title mb-0">Personal Information</h5>
                             <button class="btn btn-link btn-sm" @onclick="() => GoToStep(1)">Edit</button>
                         </div>
                         <dl class="row mb-0">
                             <dt class="col-sm-3">Full Name</dt>
                             <dd class="col-sm-9">@personalInfo.FullName</dd>
                             <dt class="col-sm-3">Email</dt>
                             <dd class="col-sm-9">@personalInfo.Email</dd>
                             <dt class="col-sm-3">Phone</dt>
                             <dd class="col-sm-9">@personalInfo.Phone</dd>
                             <dt class="col-sm-3">Address</dt>
                             <dd class="col-sm-9">@personalInfo.Address</dd>
                         </dl>
                     </div>
                 </div>

                 <!-- Work History Review -->
                 <div class="card mb-3">
                     <div class="card-body">
                         <div class="d-flex justify-content-between align-items-center mb-2">
                             <h5 class="card-title mb-0">Work History</h5>
                             <button class="btn btn-link btn-sm" @onclick="() => GoToStep(2)">Edit</button>
                         </div>
                         @foreach (var entry in workEntries.Where(e => !string.IsNullOrWhiteSpace(e.Company)))
                         {
                             <div class="mb-2 pb-2 border-bottom">
                                 <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                                 <small class="text-muted">
                                     @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") —
                                     @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                 </small>
                                 @if (!string.IsNullOrWhiteSpace(entry.Description))
                                 {
                                     <p class="mt-1 mb-0">@entry.Description</p>
                                 }
                             </div>
                         }
                     </div>
                 </div>

                 <!-- References Review -->
                 <div class="card mb-3">
                     <div class="card-body">
                         <div class="d-flex justify-content-between align-items-center mb-2">
                             <h5 class="card-title mb-0">References</h5>
                             <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
                         </div>
                         @foreach (var r in references.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
                         {
                             <div class="mb-2">
                                 <strong>@r.Name</strong>
                                 @if (!string.IsNullOrWhiteSpace(r.Relationship))
                                 {
                                     <span class="text-muted">(@r.Relationship)</span>
                                 }
                                 <br />
                                 <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</small>
                             </div>
                         }
                     </div>
                 </div>

                 <!-- Cover Letter Review -->
                 <div class="card mb-3">
                     <div class="card-body">
                         <div class="d-flex justify-content-between align-items-center mb-2">
                             <h5 class="card-title mb-0">Cover Letter</h5>
                             <button class="btn btn-link btn-sm" @onclick="() => GoToStep(4)">Edit</button>
                         </div>
                         @if (!string.IsNullOrWhiteSpace(coverLetter))
                         {
                             <p class="mb-0" style="white-space: pre-wrap;">@coverLetter</p>
                         }
                         else
                         {
                             <p class="text-muted mb-0">No cover letter provided</p>
                         }
                     </div>
                 </div>

                 <div class="d-flex justify-content-between">
                     <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                     <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isSubmitting">
                         @if (isSubmitting)
                         {
                             <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                             <span>Submitting...</span>
                         }
                         else
                         {
                             <span>Submit Application</span>
                         }
                     </button>
                 </div>
             </div>
         }
     }
 </div>

 <style>
     .step-indicator {
         padding: 0 10px;
     }

     .step-line {
         position: absolute;
         top: 20px;
         left: 40px;
         right: 40px;
         height: 2px;
         background-color: #dee2e6;
         z-index: 0;
     }

     .step-item {
         flex: 1;
         display: flex;
         flex-direction: column;
         align-items: center;
     }

     .step-circle {
         width: 40px;
         height: 40px;
         border-radius: 50%;
         display: flex;
         align-items: center;
         justify-content: center;
         font-weight: bold;
         font-size: 0.9rem;
         margin-bottom: 6px;
         transition: all 0.2s;
     }

     .step-circle[role="button"]:hover {
         transform: scale(1.1);
         box-shadow: 0 2px 8px rgba(0,0,0,0.15);
     }

     .step-label {
         font-size: 0.75rem;
         max-width: 80px;
         line-height: 1.2;
     }
 </style>

 @code {
     int currentStep = 1;
     int highestCompletedStep = 0;

     PersonalInfoModel personalInfo = new();
     List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
     List<ReferenceModel> references = new() { new ReferenceModel() };
     string coverLetter = "";

     string? emailError;
     string? validationError;
     bool isSubmitting;
     bool isSubmitted;
     int? applicationId;

     void GoToStep(int step)
     {
         if (step <= highestCompletedStep + 1)
         {
             currentStep = step;
             validationError = null;
             emailError = null;
         }
     }

     async Task NextStep()
     {
         validationError = null;
         emailError = null;

         switch (currentStep)
         {
             case 1:
                 if (string.IsNullOrWhiteSpace(personalInfo.FullName) ||
                     string.IsNullOrWhiteSpace(personalInfo.Email) ||
                     string.IsNullOrWhiteSpace(personalInfo.Phone) ||
                     string.IsNullOrWhiteSpace(personalInfo.Address))
                 {
                     validationError = "Please fill in all required fields.";
                     return;
                 }
                 var emailValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
                 if (!emailValid)
                 {
                     emailError = "Please enter a valid email address.";
                     return;
                 }
                 break;

             case 2:
                 if (!workEntries.Any(e => !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title)))
                 {
                     validationError = "At least one position must have a Company and Title.";
                     return;
                 }
                 break;

             case 3:
                 if (!references.Any(r => !string.IsNullOrWhiteSpace(r.Name) && !string.IsNullOrWhiteSpace(r.Email)))
                 {
                     validationError = "At least one reference must have a Name and Email.";
                     return;
                 }
                 break;

             case 4:
                 break;
         }

         highestCompletedStep = Math.Max(highestCompletedStep, currentStep);
         currentStep++;
     }

     void PreviousStep()
     {
         if (currentStep > 1) currentStep--;
         validationError = null;
         emailError = null;
     }

     async Task SubmitApplication()
     {
         isSubmitting = true;
         StateHasChanged();

         var application = new JobApplication(
             new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
             new WorkHistory(workEntries
                 .Where(e => !string.IsNullOrWhiteSpace(e.Company))
                 .Select(e => new WorkEntry(e.Company, e.Title ?? "", e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description ?? ""))
                 .ToList()),
             references
                 .Where(r => !string.IsNullOrWhiteSpace(r.Name))
                 .Select(r => new Reference(r.Name, r.Relationship ?? "", r.Email ?? "", r.Phone ?? ""))
                 .ToList(),
             coverLetter ?? ""
         );

         applicationId = await ApplicationService.SubmitApplicationAsync(application);
         isSubmitting = false;
         isSubmitted = true;
         StateHasChanged();
     }

     class PersonalInfoModel
     {
         public string FullName { get; set; } = "";
         public string Email { get; set; } = "";
         public string Phone { get; set; } = "";
         public string Address { get; set; } = "";
     }

     class WorkEntryModel
     {
         public string Company { get; set; } = "";
         public string Title { get; set; } = "";
         public DateTime? StartDate { get; set; }
         public DateTime? EndDate { get; set; }
         public bool IsCurrent { get; set; }
         public string Description { get; set; } = "";
     }

     class ReferenceModel
     {
         public string Name { get; set; } = "";
         public string Relationship { get; set; } = "";
         public string Email { get; set; } = "";
         public string Phone { get; set; } = "";
     }
 }
